argv:
query=query($owner: String!, $repo: String!, $p0: String!, $p1: String!) {
  repository(owner: $owner, name: $repo) {
    p0: pullRequests(headRefName: $p0, first: 1, orderBy: {field: CREATED_AT, direction: DESC}) { nodes { number url state mergedAt } }
    p1: pullRequests(headRefName: $p1, first: 1, orderBy: {field: CREATED_AT, direction: DESC}) { nodes { number url state mergedAt } }
  }
}
